initJs:
function(container, apiUrl, tables) {
  let currentPage = 1;
  let pageSize = 20;
  let filteredLogs = [];
  let allLogs = [];
  let autoUpdateInterval = null;

  // 業務ロジックモジュールのインポート
  const { 
    collectSalesData, 
    collectWeatherData, 
    collectEventData, 
    collectSeasonalData 
  } = window.aivicLogic || {};

  // データ収集ログのテーブルインデックスを取得
  const logTableIndex = tables.findIndex(t => t.tableName === 'データ収集ログ');

  // ステータス表示用の関数
  function getStatusBadge(status) {
    const statusMap = {
      '成功': { class: 'status-success', text: '成功' },
      '失敗': { class: 'status-error', text: '失敗' },
      '警告': { class: 'status-warning', text: '警告' },
      '実行中': { class: 'status-running', text: '実行中' }
    };
    const statusInfo = statusMap[status] || { class: 'status-success', text: status };
    return `<span class="status-badge ${statusInfo.class}">${statusInfo.text}</span>`;
  }

  // 日時フォーマット関数
  function formatDateTime(dateStr) {
    if (!dateStr) return '';
    const date = new Date(dateStr);
    return date.toLocaleString('ja-JP', {
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit',
      second: '2-digit'
    });
  }

  // テーブル再描画関数
  function renderRows(logs) {
    const tbody = container.querySelector('#log-table-body');
    if (!logs || logs.length === 0) {
      tbody.innerHTML = '<tr><td colspan="8" style="text-align: center; padding: 40px; color: var(--text-muted);">該当するログが見つかりません</td></tr>';
      return;
    }

    const startIndex = (currentPage - 1) * pageSize;
    const endIndex = startIndex + pageSize;
    const pageData = logs.slice(startIndex, endIndex);

    tbody.innerHTML = pageData.map(log => `
      <tr class="log-row" data-id="${log.ログID || log.id}" style="border-bottom: 1px solid var(--border);">
        <td style="padding: 12px 16px; color: var(--text);">${(log.ログID || log.id || '').substring(0, 8)}...</td>
        <td style="padding: 12px 16px; color: var(--text);">${log.データ種別 || ''}</td>
        <td style="padding: 12px 16px; color: var(--text);">${log.データソース || ''}</td>
        <td style="padding: 12px 16px; color: var(--text);">${formatDateTime(log.収集開始日時)}</td>
        <td style="padding: 12px 16px;">${getStatusBadge(log.処理ステータス || '成功')}</td>
        <td style="padding: 12px 16px; color: var(--text); text-align: right;">${log.収集件数 || 0}</td>
        <td style="padding: 12px 16px; color: var(--text); text-align: right;">${log.エラー件数 || 0}</td>
        <td style="padding: 12px 16px;">
          ${log.処理ステータス === '失敗' ? `<button class="action-btn secondary retry-btn" data-id="${log.ログID || log.id}" style="margin-right: 8px; padding: 4px 8px; font-size: 12px;">再実行</button>` : ''}
          <button class="action-btn secondary detail-btn" data-id="${log.ログID || log.id}" style="padding: 4px 8px; font-size: 12px;">詳細</button>
        </td>
      </tr>
    `).join('');

    updatePagination(logs.length);
  }

  // ページネーション更新
  function updatePagination(totalCount) {
    const totalPages = Math.ceil(totalCount / pageSize);
    const paginationContainer = container.querySelector('#pagination-container');

    if (!paginationContainer) return;

    if (totalPages <= 1) {
      paginationContainer.innerHTML = '';
      return;
    }

    let paginationHtml = `
      <button class="pagination-btn" ${currentPage === 1 ? 'disabled' : ''} data-page="prev">前へ</button>
    `;

    const startPage = Math.max(1, currentPage - 2);
    const endPage = Math.min(totalPages, currentPage + 2);

    if (startPage > 1) {
      paginationHtml += `<button class="pagination-btn" data-page="1">1</button>`;
      if (startPage > 2) {
        paginationHtml += `<span class="pagination-ellipsis">...</span>`;
      }
    }

    for (let i = startPage; i <= endPage; i++) {
      paginationHtml += `<button class="pagination-btn ${i === currentPage ? 'active' : ''}" data-page="${i}">${i}</button>`;
    }

    if (endPage < totalPages) {
      if (endPage < totalPages - 1) {
        paginationHtml += `<span class="pagination-ellipsis">...</span>`;
      }
      paginationHtml += `<button class="pagination-btn" data-page="${totalPages}">${totalPages}</button>`;
    }

    paginationHtml += `
      <button class="pagination-btn" ${currentPage === totalPages ? 'disabled' : ''} data-page="next">次へ</button>
    `;

    paginationContainer.innerHTML = paginationHtml;
  }

  // データ収集実行
  async function executeDataCollection(dataType) {
    try {
      let result;
      const startTime = new Date().toISOString();

      // ログエントリを作成
      const logEntry = {
        ログID: `log_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
        データ種別: dataType,
        データソース: getDataSourceByType(dataType),
        収集開始日時: startTime,
        処理ステータス: '実行中',
        収集件数: 0,
        エラー件数: 0
      };

      // ログテーブルに追加
      if (logTableIndex >= 0) {
        await window.aivicApi.save(logTableIndex, logEntry);
      }

      // 業務ロジック呼び出し
      switch (dataType) {
        case '売上データ':
          if (collectSalesData) {
            result = await collectSalesData();
          }
          break;
        case '天候データ':
          if (collectWeatherData) {
            result = await collectWeatherData();
          }
          break;
        case 'イベントデータ':
          if (collectEventData) {
            result = await collectEventData();
          }
          break;
        case '季節データ':
          if (collectSeasonalData) {
            result = await collectSeasonalData();
          }
          break;
        default:
          throw new Error(`未対応のデータ種別: ${dataType}`);
      }

      // 結果をログに反映
      logEntry.処理ステータス = '成功';
      logEntry.収集件数 = result?.count || 0;
      logEntry.エラー件数 = result?.errorCount || 0;
      logEntry.収集終了日時 = new Date().toISOString();

      if (logTableIndex >= 0) {
        await window.aivicApi.update(logTableIndex, logEntry.ログID, logEntry);
      }

      window.aivicNotify.success(`${dataType}の収集が完了しました`);
      await loadLogs();

    } catch (error) {
      console.error('データ収集エラー:', error);
      window.aivicNotify.error(`${dataType}の収集に失敗しました: ${error.message}`);

      // エラーログを更新
      if (logTableIndex >= 0) {
        const errorLogEntry = {
          ログID: `log_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
          データ種別: dataType,
          データソース: getDataSourceByType(dataType),
          収集開始日時: new Date().toISOString(),
          処理ステータス: '失敗',
          収集件数: 0,
          エラー件数: 1,
          エラーメッセージ: error.message
        };
        await window.aivicApi.save(logTableIndex, errorLogEntry);
        await loadLogs();
      }
    }
  }

  // データ種別からデータソースを取得
  function getDataSourceByType(dataType) {
    const sourceMap = {
      '売上データ': 'POS システム',
      '天候データ': '気象庁 API',
      'イベントデータ': 'イベント管理システム',
      '季節データ': 'カレンダー API'
    };
    return sourceMap[dataType] || '不明';
  }

  // ログデータ読み込み
  async function loadLogs() {
    try {
      if (logTableIndex >= 0) {
        const response = await window.aivicApi.list(logTableIndex);
        allLogs = response.data || [];
        applyFilters();
      }
    } catch (error) {
      console.error('ログ読み込みエラー:', error);
      window.aivicNotify.error('ログの読み込みに失敗しました');
    }
  }

  // フィルター適用
  function applyFilters() {
    const statusFilter = container.querySelector('#status-filter')?.value || '';
    const dataTypeFilter = container.querySelector('#data-type-filter')?.value || '';
    const dateFromFilter = container.querySelector('#date-from-filter')?.value || '';
    const dateToFilter = container.querySelector('#date-to-filter')?.value || '';

    filteredLogs = allLogs.filter(log => {
      if (statusFilter && log.処理ステータス !== statusFilter) return false;
      if (dataTypeFilter && log.データ種別 !== dataTypeFilter) return false;
      if (dateFromFilter && log.収集開始日時 < dateFromFilter) return false;
      if (dateToFilter && log.収集開始日時 > dateToFilter) return false;
      return true;
    });

    currentPage = 1;
    renderRows(filteredLogs);
  }

  // 再実行処理
  async function retryDataCollection(logId) {
    try {
      const log = allLogs.find(l => (l.ログID || l.id) === logId);
      if (!log) {
        window.aivicNotify.error('対象のログが見つかりません');
        return;
      }

      await executeDataCollection(log.データ種別);
    } catch (error) {
      console.error('再実行エラー:', error);
      window.aivicNotify.error('再実行に失敗しました');
    }
  }

  // 詳細表示
  function showLogDetail(logId) {
    const log = allLogs.find(l => (l.ログID || l.id) === logId);
    if (!log) {
      window.aivicNotify.error('対象のログが見つかりません');
      return;
    }

    const detailHtml = `
      <div class="log-detail-modal" style="position: fixed; top: 0; left: 0; width: 100%; height: 100%; background: rgba(0,0,0,0.5); z-index: 1000; display: flex; align-items: center; justify-content: center;">
        <div class="modal-content" style="background: var(--bg); padding: 24px; border-radius: 8px; max-width: 600px; width: 90%; max-height: 80%; overflow-y: auto;">
          <div class="modal-header" style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 20px; border-bottom: 1px solid var(--border); padding-bottom: 16px;">
            <h3 style="margin: 0; color: var(--text);">ログ詳細</h3>
            <button class="close-modal-btn" style="background: none; border: none; font-size: 24px; cursor: pointer; color: var(--text);">&times;</button>
          </div>
          <div class="modal-body">
            <div class="detail-row" style="margin-bottom: 12px;">
              <strong style="color: var(--text);">ログID:</strong> ${log.ログID || log.id}
            </div>
            <div class="detail-row" style="margin-bottom: 12px;">
              <strong style="color: var(--text);">データ種別:</strong> ${log.データ種別 || ''}
            </div>
            <div class="detail-row" style="margin-bottom: 12px;">
              <strong style="color: var(--text);">データソース:</strong> ${log.データソース || ''}
            </div>
            <div class="detail-row" style="margin-bottom: 12px;">
              <strong style="color: var(--text);">収集開始日時:</strong> ${formatDateTime(log.収集開始日時)}
            </div>
            <div class="detail-row" style="margin-bottom: 12px;">
              <strong style="color: var(--text);">収集終了日時:</strong> ${formatDateTime(log.収集終了日時)}
            </div>
            <div class="detail-row" style="margin-bottom: 12px;">
              <strong style="color: var(--text);">処理ステータス:</strong> ${getStatusBadge(log.処理ステータス)}
            </div>
            <div class="detail-row" style="margin-bottom: 12px;">
              <strong style="color: var(--text);">収集件数:</strong> ${log.収集件数 || 0}
            </div>
            <div class="detail-row" style="margin-bottom: 12px;">
              <strong style="color: var(--text);">エラー件数:</strong> ${log.エラー件数 || 0}
            </div>
            ${log.エラーメッセージ ? `
              <div class="detail-row" style="margin-bottom: 12px;">
                <strong style="color: var(--text);">エラーメッセージ:</strong>
                <div style="background: var(--bg-secondary); padding: 8px; border-radius: 4px; margin-top: 4px; color: var(--text);">${log.エラーメッセージ}</div>
              </div>
            ` : ''}
          </div>
        </div>
      </div>
    `;

    document.body.insertAdjacentHTML('beforeend', detailHtml);

    const modal = document.querySelector('.log-detail-modal');
    const closeBtn = modal.querySelector('.close-modal-btn');

    closeBtn.addEventListener('click', () => {
      modal.remove();
    });

    modal.addEventListener('click', (e) => {
      if (e.target === modal) {
        modal.remove();
      }
    });
  }

  // 自動更新の開始/停止
  function toggleAutoUpdate() {
    const autoUpdateBtn = container.querySelector('#auto-update-btn');
    if (autoUpdateInterval) {
      clearInterval(autoUpdateInterval);
      autoUpdateInterval = null;
      if (autoUpdateBtn) {
        autoUpdateBtn.textContent = '自動更新開始';
        autoUpdateBtn.classList.remove('active');
      }
    } else {
      autoUpdateInterval = setInterval(loadLogs, 30000); // 30秒間隔
      if (autoUpdateBtn) {
        autoUpdateBtn.textContent = '自動更新停止';
        autoUpdateBtn.classList.add('active');
      }
    }
  }

  // イベントリスナーの設定
  function setupEventListeners() {
    // データ収集ボタン
    const collectSalesBtn = container.querySelector('#collect-sales-btn');
    const collectWeatherBtn = container.querySelector('#collect-weather-btn');
    const collectEventBtn = container.querySelector('#collect-event-btn');
    const collectSeasonalBtn = container.querySelector('#collect-seasonal-btn');

    if (collectSalesBtn) {
      collectSalesBtn.addEventListener('click', () => executeDataCollection('売上データ'));
    }
    if (collectWeatherBtn) {
      collectWeatherBtn.addEventListener('click', () => executeDataCollection('天候データ'));
    }
    if (collectEventBtn) {
      collectEventBtn.addEventListener('click', () => executeDataCollection('イベントデータ'));
    }
    if (collectSeasonalBtn) {
      collectSeasonalBtn.addEventListener('click', () => executeDataCollection('季節データ'));
    }

    // フィルター
    const statusFilter = container.querySelector('#status-filter');
    const dataTypeFilter = container.querySelector('#data-type-filter');
    const dateFromFilter = container.querySelector('#date-from-filter');
    const dateToFilter = container.querySelector('#date-to-filter');
    const clearFiltersBtn = container.querySelector('#clear-filters-btn');

    if (statusFilter) statusFilter.addEventListener('change', applyFilters);
    if (dataTypeFilter) dataTypeFilter.addEventListener('change', applyFilters);
    if (dateFromFilter) dateFromFilter.addEventListener('change', applyFilters);
    if (dateToFilter) dateToFilter.addEventListener('change', applyFilters);

    if (clearFiltersBtn) {
      clearFiltersBtn.addEventListener('click', () => {
        if (statusFilter) statusFilter.value = '';
        if (dataTypeFilter) dataTypeFilter.value = '';
        if (dateFromFilter) dateFromFilter.value = '';
        if (dateToFilter) dateToFilter.value = '';
        applyFilters();
      });
    }

    // 更新ボタン
    const refreshBtn = container.querySelector('#refresh-btn');
    if (refreshBtn) {
      refreshBtn.addEventListener('click', loadLogs);
    }

    // 自動更新ボタン
    const autoUpdateBtn = container.querySelector('#auto-update-btn');
    if (autoUpdateBtn) {
      autoUpdateBtn.addEventListener('click', toggleAutoUpdate);
    }

    // テーブル内のボタン（イベント委譲）
    const logTableBody = container.querySelector('#log-table-body');
    if (logTableBody) {
      logTableBody.addEventListener('click', (e) => {
        if (e.target.classList.contains('retry-btn')) {
          const logId = e.target.getAttribute('data-id');
          retryDataCollection(logId);
        } else if (e.target.classList.contains('detail-btn')) {
          const logId = e.target.getAttribute('data-id');
          showLogDetail(logId);
        }
      });
    }

    // ページネーション（イベント委譲）
    const paginationContainer = container.querySelector('#pagination-container');
    if (paginationContainer) {
      paginationContainer.addEventListener('click', (e) => {
        if (e.target.classList.contains('pagination-btn') && !e.target.disabled) {
          const page = e.target.getAttribute('data-page');
          if (page === 'prev') {
            currentPage = Math.max(1, currentPage - 1);
          } else if (page === 'next') {
            const totalPages = Math.ceil(filteredLogs.length / pageSize);
            currentPage = Math.min(totalPages, currentPage + 1);
          } else {
            currentPage = parseInt(page);
          }
          renderRows(filteredLogs);
        }
      });
    }
  }

  // 初期化
  async function initialize() {
    setupEventListeners();
    await loadLogs();
  }

  // クリーンアップ
  function cleanup() {
    if (autoUpdateInterval) {
      clearInterval(autoUpdateInterval);
      autoUpdateInterval = null;
    }
  }

  // ページ離脱時のクリーンアップ
  window.addEventListener('beforeunload', cleanup);

  // 初期化実行
  initialize();

  return {
    cleanup,
    loadLogs,
    executeDataCollection
  };
}
